/**
 * Контракт между платформой и играми. Имена фиксированы: на них опираются все игры.
 * Игра импортирует из платформы только `platform/sdk/*`.
 */

/**
 * Генератор случайных чисел. `next()` возвращает число в [0, 1). Передаётся игре платформой.
 * На каждый вызов `start`/`action` игра получает отдельный замороженный объект; сохранять его между вызовами нельзя.
 */
export interface Rng {
  next(): number;
}

/**
 * Результат шага игры.
 * - `continue` — раунд продолжается, нужен следующий ход;
 * - `finished` — раунд окончен, `payout` — полная сумма к зачислению (0 при проигрыше).
 */
export type Step<S> =
  | { status: 'continue'; state: S }
  | { status: 'finished'; state: S; payout: number };

/**
 * Серверный модуль игры. Платформа вызывает его внутри раунда: списывает ставку до `start`
 * и зачисляет `payout` после шага со статусом `finished`. Игра не знает о кошельке и балансе.
 *
 * Состояние `S` и параметры `P` должны сериализоваться в JSON: платформа хранит их на диске.
 *
 * Порядок внутри `start`/`action`: сначала проверить `action` (бросить `INVALID_ACTION`) и всё, что может упасть,
 * и только потом обращаться к `rng`. После первого `rng.next()` исключения запрещены, а шаг должен быть корректным:
 * иначе повтор хода давал бы новый исход. Если игра всё же упала после `rng.next()`, платформа не возвращает
 * ставку и не даёт повторить ход: раунд блокируется для ручного разбора, клиент получает `INTERNAL_ERROR`.
 * Если игра упала в `start` до обращения к `rng`, раунд аннулируется, ставка возвращается.
 *
 * Серверный модуль работает в процессе ядра. Кроме `platform/sdk/*`, ему запрещены `process`, `globalThis`,
 * `require`, динамический `import()`, `fetch`, `eval`/`Function` и модули `node:*`: игра — чистая функция от
 * `ctx` и состояния.
 */
export interface GameModule<P = any, S = any, A = any> {
  /** Идентификатор игры, совпадает с `id` в `manifest.json`. */
  id: string;
  /** Проверяет и нормализует параметры раунда. Бросает `GameError('INVALID_PARAMS')`. */
  validateParams(params: unknown): P;
  /** Начинает раунд (ставка уже списана). */
  start(ctx: { bet: number; params: P; rng: Rng }): Step<S>;
  /** Ход игрока. Бросает `GameError('INVALID_ACTION')` на недопустимое действие. */
  action(ctx: { bet: number; params: P; state: S; action: A; rng: Rng }): Step<S>;
  /** Что можно показать клиенту. До конца раунда (`finished = false`) скрытое не раскрывается. */
  publicView(state: S, finished: boolean): unknown;
}

/** Ошибка игры с кодом (`INVALID_PARAMS`, `INVALID_ACTION`). Платформа передаёт код клиенту. */
export class GameError extends Error {
  /** Код ошибки. */
  code: string;

  /**
   * @param code код ошибки, например `INVALID_PARAMS`
   * @param message необязательное пояснение для игрока
   */
  constructor(code: string, message?: string) {
    super(message ?? code);
    this.name = 'GameError';
    this.code = code;
  }
}
// «Монетка»: игрок выбирает сторону, один бросок в start определяет исход и закрывает раунд.
// Спецификация: games/coin/spec.md. Решения: decisions/coin.md (D-001…D-006).
import type { GameModule, Rng, Step } from '../../../platform/sdk/types.ts';
import { GameError } from '../../../platform/sdk/types.ts';

/** Сторона монеты. */
export type Side = 'heads' | 'tails';

/** Нормализованные параметры раунда. */
export interface CoinParams {
  side: Side;
}

/** Состояние раунда: выбранная сторона, выпавшая сторона и признак выигрыша. */
export interface CoinState {
  side: Side;
  outcome: Side;
  win: boolean;
}

/** Коэффициент выплаты при угадывании: честные 2 минус 2 % house edge (D-001). */
export const PAYOUT_MULTIPLIER = 1.96;

function isSide(value: unknown): value is Side {
  return value === 'heads' || value === 'tails';
}

/** Исход по одному числу rng: r < 0.5 → heads, иначе tails (D-002). */
function flip(rng: Rng): Side {
  return rng.next() < 0.5 ? 'heads' : 'tails';
}

/**
 * Серверный модуль «Монетки».
 * Тип `P` оставлен по умолчанию (как у заготовки): платформа отдаёт в `start` результат `validateParams`,
 * а `start` ещё раз нормализует параметры до обращения к rng (D-013).
 *
 * - `validateParams(params)` — возвращает `{ side }`; бросает `GameError('INVALID_PARAMS')`, если
 *   `params` не объект или `side` не `'heads'`/`'tails'` (D-005).
 * - `start({ bet, params, rng })` — один вызов `rng.next()`, возвращает закрытый шаг
 *   `{ status: 'finished', state, payout }`, где `payout = win ? bet × 1.96 : 0` (D-001…D-003).
 * - `action()` — всегда бросает `GameError('INVALID_ACTION')`: ходов внутри раунда нет.
 * - `publicView(state)` — `{ side, outcome, win }`, скрытого нет (D-006).
 */
const game: GameModule = {
  id: 'coin',

  validateParams(params: unknown): CoinParams {
    if (typeof params !== 'object' || params === null || Array.isArray(params)) {
      throw new GameError('INVALID_PARAMS', 'Параметры должны быть объектом { side }');
    }
    const side = (params as { side?: unknown }).side;
    if (!isSide(side)) {
      throw new GameError('INVALID_PARAMS', 'side должен быть "heads" или "tails"');
    }
    return { side };
  },

  start({ bet, params, rng }: { bet: number; params: CoinParams; rng: Rng }): Step<CoinState> {
    // Всё, что может упасть, — до обращения к rng (контракт platform/sdk/types.ts).
    const { side } = game.validateParams(params);
    const outcome = flip(rng);
    const win = outcome === side;
    return {
      status: 'finished',
      state: { side, outcome, win },
      payout: win ? bet * PAYOUT_MULTIPLIER : 0,
    };
  },

  action(): Step<CoinState> {
    throw new GameError('INVALID_ACTION', 'Раунд «Монетки» состоит из одного броска');
  },

  publicView(state: CoinState): { side: Side; outcome: Side; win: boolean } {
    return { side: state.side, outcome: state.outcome, win: state.win };
  },
};

/** Модуль игры `coin` (`GameModule`), который платформа загружает по `manifest.json`. */
export default game;
<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Монетка</title>
<style>
  :root { color-scheme: light dark; --accent: #2563eb; --win: #16a34a; --lose: #dc2626; --muted: #6b7280; }
  * { box-sizing: border-box; }
  body { margin: 0; font-family: system-ui, sans-serif; background: Canvas; color: CanvasText; }
  main { max-width: 420px; margin: 0 auto; padding: 24px 16px; display: grid; gap: 16px; }
  h1 { margin: 0; font-size: 24px; }
  .row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
  .label { color: var(--muted); font-size: 14px; }
  .balance { font-size: 20px; font-weight: 600; }
  input { font: inherit; padding: 8px; width: 100px; }
  button { font: inherit; padding: 10px 16px; border-radius: 8px; border: 1px solid var(--muted); background: transparent; color: inherit; cursor: pointer; }
  button[aria-pressed="true"] { border-color: var(--accent); background: var(--accent); color: #fff; }
  button:disabled { opacity: .5; cursor: default; }
  #play { background: var(--accent); color: #fff; border-color: var(--accent); width: 100%; font-weight: 600; }
  .coin { width: 120px; height: 120px; margin: 0 auto; border-radius: 50%; display: grid; place-items: center;
          border: 4px solid #ca8a04; background: #facc15; color: #713f12; font-size: 18px; font-weight: 700; }
  [data-state="playing"] .coin { animation: spin .4s linear infinite; }
  @keyframes spin { from { transform: rotateY(0); } to { transform: rotateY(360deg); } }
  .result { text-align: center; min-height: 1.5em; }
  [data-state="won"] .result { color: var(--win); }
  [data-state="lost"] .result { color: var(--lose); }
  .error { color: var(--lose); min-height: 1.2em; }
</style>
</head>
<body>
<main data-testid="game" data-state="idle">
  <h1>Монетка</h1>
  <div class="row"><span class="label">Баланс:</span> <span class="balance" data-testid="balance">—</span></div>

  <div class="row">
    <label class="label" for="bet">Ставка</label>
    <input id="bet" data-testid="bet-input" type="number" step="0.01" min="1" max="10" value="1">
    <span class="label" id="limits"></span>
  </div>

  <div class="row" role="group" aria-label="Сторона">
    <button type="button" data-testid="side-heads" data-side="heads" aria-pressed="true">Орёл</button>
    <button type="button" data-testid="side-tails" data-side="tails" aria-pressed="false">Решка</button>
  </div>

  <button type="button" id="play" data-testid="play">Бросить</button>

  <div class="coin" data-testid="outcome" aria-live="polite"></div>
  <div class="result">Выплата: <span data-testid="payout">—</span></div>
  <div class="error" data-testid="error" role="alert"></div>
</main>
<script src="/sdk.js"></script>
<script>
(function () {
  'use strict';

  var SIDE_NAMES = { heads: 'Орёл', tails: 'Решка' };
  var ERROR_TEXT = {
    BET_OUT_OF_LIMITS: 'Ставка вне лимитов',
    INSUFFICIENT_FUNDS: 'Недостаточно средств',
    INVALID_PARAMS: 'Неверные параметры',
    NETWORK_ERROR: 'Нет связи с сервером',
  };
  var started = false;

  function init() {
    if (started) return;
    started = true;

    var sdk = window.PlatformSDK;
    var q = function (id) { return document.querySelector('[data-testid="' + id + '"]'); };
    var root = q('game');
    var balanceEl = q('balance');
    var betInput = q('bet-input');
    var playBtn = q('play');
    var outcomeEl = q('outcome');
    var payoutEl = q('payout');
    var errorEl = q('error');
    var limitsEl = document.getElementById('limits');
    var sideButtons = [q('side-heads'), q('side-tails')];
    var side = 'heads';
    var busy = false;

    function money(n) { return Number(n).toFixed(2); }
    function setState(s) { root.setAttribute('data-state', s); }
    function setBalance(b) { if (typeof b === 'number') balanceEl.textContent = money(b); }

    function showError(e) {
      var code = (e && e.code) || 'INTERNAL_ERROR';
      var text = ERROR_TEXT[code] || (e && e.message) || 'Ошибка';
      errorEl.textContent = code + ': ' + text;
    }

    function showRound(round) {
      var view = round && round.view;
      if (!view || !view.outcome) return;
      outcomeEl.textContent = SIDE_NAMES[view.outcome] || view.outcome;
      payoutEl.textContent = money(round.payout || 0);
      setState(view.win ? 'won' : 'lost');
    }

    function selectSide(s) {
      side = s;
      sideButtons.forEach(function (b) {
        b.setAttribute('aria-pressed', b.getAttribute('data-side') === s ? 'true' : 'false');
      });
    }

    function setBusy(v) {
      busy = v;
      playBtn.disabled = v;
      sideButtons.forEach(function (b) { b.disabled = v; });
    }

    sideButtons.forEach(function (b) {
      b.addEventListener('click', function () { if (!busy) selectSide(b.getAttribute('data-side')); });
    });

    playBtn.addEventListener('click', function () {
      if (busy) return;
      var bet = Number(betInput.value);
      errorEl.textContent = '';
      outcomeEl.textContent = '';
      payoutEl.textContent = '—';
      setBusy(true);
      setState('playing');
      sdk.startRound(bet, { side: side }).then(function (round) {
        setBalance(round.balance);
        showRound(round);
      }, function (e) {
        showError(e);
        // Раунд не состоялся: прошлый исход уже стёрт, возвращаемся к ожиданию броска.
        setState('idle');
      }).then(function () { setBusy(false); });
    });

    setBusy(true);
    sdk.open().then(function (info) {
      setBalance(info.balance);
      if (info.limits) {
        betInput.min = String(info.limits.min);
        betInput.max = String(info.limits.max);
        limitsEl.textContent = 'от ' + info.limits.min + ' до ' + info.limits.max;
      }
      // Раунд «Монетки» закрывается в том же запросе, но если платформа вернула раунд — показываем его.
      if (info.activeRound) {
        if (info.activeRound.view && info.activeRound.view.side) selectSide(info.activeRound.view.side);
        showRound(info.activeRound);
      }
    }, showError).then(function () { setBusy(false); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
</script>
</body>
</html>
{
  "id": "coin",
  "title": "Монетка",
  "server": "server/index.ts",
  "ui": "ui/index.html"
}
{
  "id": "mines",
  "title": "Мины",
  "server": "server/index.ts",
  "ui": "ui/index.html"
}
// Заглушка, созданная оркестратором. Реализацию пишет агент-разработчик.
import type { GameModule } from '../../../platform/sdk/types.ts';

const notImplemented = (): never => {
  throw new Error('NOT_IMPLEMENTED');
};

/** Заглушка игры mines: все методы бросают NOT_IMPLEMENTED. */
const game: GameModule = {
  id: 'mines',
  validateParams: notImplemented,
  start: notImplemented,
  action: notImplemented,
  publicView: notImplemented,
};

export default game;
<!doctype html>
<meta charset="utf-8">
<title>Мины</title>
<p>NOT_IMPLEMENTED</p>

