// Контракт серверного модуля «Мин» (games/mines/spec.md, SC-14; platform/sdk/types.ts).
// Проверяются публичные методы GameModule: число вызовов rng, неизменяемость state, сериализуемость, коды ошибок.
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import game from '../server/index.ts';
import { GameError } from '../../../platform/sdk/types.ts';

/** rng, который отдаёт заданные числа и бросает, когда они кончились; считает вызовы. */
function countingRng(values: number[]) {
  let calls = 0;
  const rng = {
    next(): number {
      calls += 1;
      if (calls > values.length) throw new Error('rng: лишний вызов');
      return values[calls - 1] as number;
    },
  };
  return { rng, calls: () => calls };
}

function gameErrorCode(fn: () => unknown): string {
  try {
    const v = fn();
    throw new Error(`ожидалась GameError, а вызов вернул ${JSON.stringify(v)}`);
  } catch (e: any) {
    expect(e).toBeInstanceOf(GameError);
    return e.code;
  }
}

const START_STATE = { mines: [7, 12, 19], revealed: [], hit: null, outcome: null };

describe('Мины: контракт модуля игры', () => {
  beforeEach(() => {
    vi.spyOn(Math, 'random').mockImplementation(() => {
      throw new Error('Math.random запрещён в игре');
    });
  });
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('SC-14: id и validateParams нормализуют параметры до {}', () => {
    expect(game.id).toBe('mines');
    expect(game.validateParams({ mines: 5 })).toEqual({});
    expect(game.validateParams(undefined)).toEqual({});
    expect(game.validateParams({})).toEqual({});
    expect(game.validateParams({ mines: 10, extra: 1 })).toEqual({});
  });

  it('SC-14: validateParams бросает GameError INVALID_PARAMS на null, массив, строку и число', () => {
    for (const p of [null, [], 'x', 5]) {
      expect(gameErrorCode(() => game.validateParams(p)), `params = ${JSON.stringify(p)}`).toBe('INVALID_PARAMS');
    }
  });

  it('SC-14: start делает ровно 3 вызова rng, состояние сериализуемо, publicView не раскрывает мины', () => {
    const { rng, calls } = countingRng([0.5, 0.75, 0.25]);
    const step: any = game.start({ bet: 2, params: {}, rng });
    expect(calls()).toBe(3);
    expect(step.status).toBe('continue');
    expect(step).not.toHaveProperty('payout');
    expect(step.state).toEqual(START_STATE);
    expect(JSON.parse(JSON.stringify(step.state))).toEqual(step.state);
    expect(game.publicView(step.state, false)).toEqual({ mineCount: 3, revealed: [], multiplier: 1, nextMultiplier: 1.11 });
  });

  it('SC-14: start расставляет мины по таблице спецификации и хранит их отсортированными', () => {
    const cases: Array<[number[], number[]]> = [
      [[0.5, 0.75, 0.25], [7, 12, 19]],
      [[0, 0, 0], [0, 1, 2]],
      [[0.9999, 0.9999, 0.9999], [0, 1, 24]],
    ];
    for (const [values, mines] of cases) {
      const { rng, calls } = countingRng(values);
      const step: any = game.start({ bet: 1, params: {}, rng });
      expect(calls(), `rng ${values}`).toBe(3);
      expect(step.state, `rng ${values}`).toEqual({ mines, revealed: [], hit: null, outcome: null });
    }
  });

  it('SC-14: action reveal безопасной клетки не вызывает rng и не меняет переданный state', () => {
    const { rng: startRng } = countingRng([0.5, 0.75, 0.25]);
    const state = (game.start({ bet: 2, params: {}, rng: startRng }) as any).state;
    const snapshot = structuredClone(state);
    const { rng, calls } = countingRng([]);

    const step: any = game.action({ bet: 2, params: {}, state, action: { type: 'reveal', cell: 0 }, rng });
    expect(calls()).toBe(0);
    expect(step).toEqual({ status: 'continue', state: { mines: [7, 12, 19], revealed: [0], hit: null, outcome: null } });
    expect(state).toEqual(snapshot);
    expect(JSON.parse(JSON.stringify(step.state))).toEqual(step.state);
    expect(game.publicView(step.state, false)).toEqual({ mineCount: 3, revealed: [0], multiplier: 1.11, nextMultiplier: 1.27 });
  });

  it('SC-14: action с недопустимой клеткой бросает GameError INVALID_ACTION, rng не вызван, state не изменён', () => {
    const state = structuredClone(START_STATE);
    const snapshot = structuredClone(state);
    const { rng, calls } = countingRng([]);
    expect(gameErrorCode(() => game.action({ bet: 2, params: {}, state, action: { type: 'reveal', cell: 30 }, rng }))).toBe(
      'INVALID_ACTION',
    );
    expect(gameErrorCode(() => game.action({ bet: 2, params: {}, state, action: { type: 'cashout' }, rng }))).toBe(
      'INVALID_ACTION',
    );
    expect(calls()).toBe(0);
    expect(state).toEqual(snapshot);
  });

  it('SC-14: cashout при revealed = [0] — finished, payout 2 × 1.11 = 2.22, outcome cashout', () => {
    const state = { mines: [7, 12, 19], revealed: [0], hit: null, outcome: null };
    const snapshot = structuredClone(state);
    const { rng, calls } = countingRng([]);
    const step: any = game.action({ bet: 2, params: {}, state, action: { type: 'cashout' }, rng });
    expect(calls()).toBe(0);
    expect(step.status).toBe('finished');
    expect(step.payout).toBeCloseTo(2.22, 9);
    expect(step.state).toEqual({ mines: [7, 12, 19], revealed: [0], hit: null, outcome: 'cashout' });
    expect(state).toEqual(snapshot);
    expect(game.publicView(step.state, true)).toEqual({
      mineCount: 3,
      revealed: [0],
      multiplier: 1.11,
      nextMultiplier: null,
      mines: [7, 12, 19],
      hit: null,
      outcome: 'cashout',
    });
  });

  it('SC-14: reveal мины — finished, payout 0, hit и outcome mine, rng не вызван', () => {
    const state = { mines: [7, 12, 19], revealed: [0], hit: null, outcome: null };
    const snapshot = structuredClone(state);
    const { rng, calls } = countingRng([]);
    const step: any = game.action({ bet: 2, params: {}, state, action: { type: 'reveal', cell: 7 }, rng });
    expect(calls()).toBe(0);
    expect(step.status).toBe('finished');
    expect(step.payout).toBe(0);
    expect(step.state).toEqual({ mines: [7, 12, 19], revealed: [0], hit: 7, outcome: 'mine' });
    expect(state).toEqual(snapshot);
  });

  it('SC-14: 22-я безопасная клетка завершает раунд с payout bet × 2254 и outcome cleared', () => {
    const revealed = Array.from({ length: 21 }, (_, i) => i + 3); // 3…23
    const state = { mines: [0, 1, 2], revealed, hit: null, outcome: null };
    const { rng, calls } = countingRng([]);
    const step: any = game.action({ bet: 1, params: {}, state, action: { type: 'reveal', cell: 24 }, rng });
    expect(calls()).toBe(0);
    expect(step.status).toBe('finished');
    expect(step.payout).toBeCloseTo(2254, 9);
    expect(step.state).toEqual({ mines: [0, 1, 2], revealed: [...revealed, 24], hit: null, outcome: 'cleared' });
    expect(revealed).toHaveLength(21);
  });

  it('SC-14: publicView открытого раунда не раскрывает мины ни при каком k', () => {
    const state = { mines: [7, 12, 19], revealed: [0, 6, 24], hit: null, outcome: null };
    const view = game.publicView(state, false);
    expect(view).toEqual({ mineCount: 3, revealed: [0, 6, 24], multiplier: 1.46, nextMultiplier: 1.69 });
    expect(JSON.stringify(view)).not.toMatch(/"mines"|"hit"|"outcome"/);
  });
});
// @vitest-environment happy-dom
// Интерфейс «Мин» (games/mines/spec.md, SC-15): ui/index.html с подменённым window.PlatformSDK.
// Внешний /sdk.js не загружается; инлайновые скрипты страницы выполняются в глобальной области, как обычный <script>.
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it, vi } from 'vitest';

// Строка import.meta.url, а не new URL(): в happy-dom глобальный URL принадлежит окну, а не Node.
const HTML_PATH = resolve(dirname(fileURLToPath(import.meta.url)), '../ui/index.html');

/** Ждёт выполнения условия, прокручивая очередь задач. */
async function waitFor(cond: () => boolean, what: string, timeoutMs = 3000): Promise<void> {
  const started = Date.now();
  for (;;) {
    let ok = false;
    try {
      ok = cond();
    } catch {
      ok = false;
    }
    if (ok) return;
    if (Date.now() - started > timeoutMs) throw new Error(`не дождались: ${what}`);
    await new Promise((r) => setTimeout(r, 5));
  }
}

const $ = (id: string): HTMLElement => {
  const el = document.querySelector(`[data-testid="${id}"]`) as HTMLElement | null;
  if (!el) throw new Error(`нет элемента data-testid="${id}"`);
  return el;
};

/** Первое число в тексте элемента (запятая как десятичный разделитель допускается). */
const numberIn = (id: string): number => {
  const m = ($(id).textContent ?? '').replace(/\s/g, '').replace(',', '.').match(/-?\d+(\.\d+)?/);
  return m ? Number(m[0]) : NaN;
};

const isDisabled = (el: HTMLElement): boolean =>
  (el as HTMLButtonElement).disabled === true || el.getAttribute('aria-disabled') === 'true';

const state = () => $('game').getAttribute('data-state');
const cellState = (i: number) => $(`cell-${i}`).getAttribute('data-cell-state');

// Слушатели, которые страница повесила на document/window: снимаются перед повторной «загрузкой»,
// чтобы скрипт прошлой загрузки не реагировал на события новой.
const tracked: Array<{ target: EventTarget; type: string; fn: any; opts: any }> = [];
let patched = false;
function trackListeners(): void {
  if (patched) return;
  patched = true;
  const g = globalThis as any;
  for (const target of [g.document, g.window] as EventTarget[]) {
    const orig = target.addEventListener.bind(target);
    (target as any).addEventListener = (type: string, fn: any, opts?: any) => {
      tracked.push({ target, type, fn, opts });
      return orig(type, fn, opts);
    };
  }
}
function dropListeners(): void {
  for (const l of tracked.splice(0)) l.target.removeEventListener(l.type, l.fn, l.opts);
}

/** «Открывает» страницу: разметка без <script>, затем подмена SDK, затем инлайновые скрипты. */
function loadPage(sdk: unknown): void {
  trackListeners();
  dropListeners();
  const html = readFileSync(HTML_PATH, 'utf8');
  const scripts: string[] = [];
  const stripped = html.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi, (_m, attrs: string, code: string) => {
    if (!/\bsrc\s*=/.test(attrs) && code.trim()) scripts.push(code);
    return '';
  });
  const doc = new DOMParser().parseFromString(stripped, 'text/html');
  for (const a of Array.from(doc.documentElement.attributes)) document.documentElement.setAttribute(a.name, a.value);
  for (const a of Array.from(doc.body.attributes)) document.body.setAttribute(a.name, a.value);
  document.head.innerHTML = doc.head.innerHTML;
  document.body.innerHTML = doc.body.innerHTML;

  const g = globalThis as any;
  g.window.PlatformSDK = sdk;
  g.PlatformSDK = sdk;
  const indirectEval: (code: string) => unknown = g.eval;
  for (const code of scripts) indirectEval(code);
  document.dispatchEvent(new g.Event('DOMContentLoaded'));
  g.window.dispatchEvent(new g.Event('load'));
}

const OPEN_VIEW_0 = { mineCount: 3, revealed: [], multiplier: 1, nextMultiplier: 1.11 };
const OPEN_VIEW_1 = { mineCount: 3, revealed: [0], multiplier: 1.11, nextMultiplier: 1.27 };

describe('Мины: интерфейс', () => {
  it('SC-15: idle → playing → открытие клетки → cashout → won, мины показаны', async () => {
    const sdk = {
      open: vi.fn(async () => ({ gameId: 'mines', balance: 100, limits: { min: 1, max: 10 }, activeRound: null })),
      startRound: vi.fn(async (_bet: unknown, _params: unknown) => ({
        roundId: 'r1',
        gameId: 'mines',
        status: 'open',
        bet: 2,
        payout: null,
        balance: 98,
        view: OPEN_VIEW_0,
      })),
      action: vi.fn(async (a: any) => {
        if (a && a.type === 'reveal' && a.cell === 0) {
          return { roundId: 'r1', gameId: 'mines', bet: 2, status: 'open', balance: 98, payout: null, view: OPEN_VIEW_1 };
        }
        if (a && a.type === 'cashout') {
          return {
            roundId: 'r1',
            gameId: 'mines',
            bet: 2,
            status: 'closed',
            balance: 100.22,
            payout: 2.22,
            view: {
              mineCount: 3,
              revealed: [0],
              multiplier: 1.11,
              nextMultiplier: null,
              mines: [7, 12, 19],
              hit: null,
              outcome: 'cashout',
            },
          };
        }
        throw { code: 'INVALID_ACTION', message: 'неожиданный ход в тесте' };
      }),
    };
    loadPage(sdk);

    // Загрузка: idle, баланс из open(), клетки и cashout заблокированы, ставка по умолчанию 1.
    await waitFor(() => sdk.open.mock.calls.length > 0 && numberIn('balance') === 100, 'баланс 100 после open()');
    expect(state()).toBe('idle');
    expect(Number(($('bet-input') as HTMLInputElement).value)).toBe(1);
    for (let i = 0; i < 25; i++) expect(isDisabled($(`cell-${i}`)), `cell-${i} в idle`).toBe(true);
    expect(isDisabled($('cashout'))).toBe(true);

    // Ставка 2 и новая игра.
    const input = $('bet-input') as HTMLInputElement;
    input.value = '2';
    input.dispatchEvent(new (globalThis as any).Event('input', { bubbles: true }));
    input.dispatchEvent(new (globalThis as any).Event('change', { bubbles: true }));
    $('play').click();
    await waitFor(() => sdk.startRound.mock.calls.length === 1, 'вызов startRound');
    expect(sdk.startRound).toHaveBeenCalledWith(2, {});
    await waitFor(() => state() === 'playing' && numberIn('balance') === 98, 'playing и баланс 98');
    expect(isDisabled($('play'))).toBe(true);
    expect(isDisabled($('cashout'))).toBe(true);
    for (let i = 0; i < 25; i++) {
      expect(cellState(i), `cell-${i} скрыта`).toBe('hidden');
      expect(isDisabled($(`cell-${i}`)), `cell-${i} доступна в playing`).toBe(false);
    }
    expect(sdk.action).not.toHaveBeenCalled();

    // Открытие клетки 0.
    $('cell-0').click();
    await waitFor(() => sdk.action.mock.calls.length === 1, 'вызов action');
    expect(sdk.action).toHaveBeenCalledWith({ type: 'reveal', cell: 0 });
    await waitFor(() => cellState(0) === 'safe', 'cell-0 safe');
    await waitFor(() => numberIn('multiplier') === 1.11, 'множитель 1.11');
    expect(numberIn('next-multiplier')).toBe(1.27);
    await waitFor(() => !isDisabled($('cashout')), 'cashout доступна при k = 1');
    expect(state()).toBe('playing');
    expect(isDisabled($('cell-0'))).toBe(true);
    expect(isDisabled($('play'))).toBe(true);
    for (let i = 1; i < 25; i++) expect(cellState(i), `cell-${i} всё ещё скрыта`).toBe('hidden');
    expect(numberIn('balance')).toBe(98);

    // Cashout.
    $('cashout').click();
    await waitFor(() => sdk.action.mock.calls.length === 2, 'вызов action cashout');
    expect(sdk.action).toHaveBeenLastCalledWith({ type: 'cashout' });
    await waitFor(() => state() === 'won', 'data-state=won');
